// Monster Factory — feature (preview) + bonus screens.
//
// Self-contained: builds its own full-screen overlay + WebGL canvas inside
// #screen and its own SpineEngine stage, so slot.js / app.js only call
//   await MonsterScreens.load();                    // once, at boot (optional)
//   await MonsterScreens.show('feature');           // before play
//   await MonsterScreens.show('bonus', { count });  // free spins won
// Requires vendor/spine-webgl.js + js/spine-engine.js loaded before this file.
//
// The skeletons are generated by scripts/monster_factory_screens.py:
// img/monster-factory/screens/{feature,bonus}_{desk,mob}/, clips `intro`
// (3s) -> `idle` (4s loop), PMA atlases. Two empty bones are the DOM contract:
// `count` (centre of the counter window, bonus only) and `tap` (hint spot).
// The game background is not in the skeleton — it is the overlay's own layer.
(function () {
  'use strict';

  const ROOT = 'img/monster-factory';
  const SCREEN_ROOT = `${ROOT}/screens`;
  const BOX = {
    desk: { x: -966, y: -470, width: 1932, height: 940 },
    mob: { x: -390, y: -708, width: 780, height: 1416 },
  };
  const BG = {
    feature: { desk: `${ROOT}/img/bg_base.jpg`, mob: `${ROOT}/img/bg_base_mob.jpg` },
    bonus: { desk: `${ROOT}/img/bg_bonus.jpg`, mob: `${ROOT}/img/bg_bonus_mob.jpg` },
  };
  const MIN_SHOW_MS = 1500; // taps before this are ignored (the hint appears then)
  const BONUS_AUTO_CLOSE_MS = 10000;
  const FADE_MS = 450;
  // Bonus counter: the plate pops in at 1.0-1.6s of intro, then the number
  // counts up over it. Sizes are in skeleton units (plate window ~130 tall).
  const COUNT_AT = 1.5;
  const COUNT_UP_S = 0.6;
  const COUNT_UNITS = 112;
  const TAP_UNITS = 46;

  const CSS = `
.mf-screen {
  position: absolute; inset: 0; z-index: 25; overflow: hidden;
  opacity: 0; visibility: hidden; pointer-events: none;
  transition: opacity ${FADE_MS}ms ease-out, visibility 0s linear ${FADE_MS}ms;
  cursor: pointer; -webkit-tap-highlight-color: transparent; user-select: none;
}
.mf-screen.is-open {
  opacity: 1; visibility: visible; pointer-events: auto;
  transition: opacity 300ms ease-out, visibility 0s;
}
.mf-screen__bg {
  position: absolute; inset: 0; background: #120a06 center / cover no-repeat;
  transform: scale(1.04); transition: transform 3.5s ease-out;
}
.mf-screen.is-open .mf-screen__bg { transform: scale(1); }
.mf-screen__shade {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(8, 4, 14, 0.35) 0%, rgba(8, 4, 14, 0.62) 70%, rgba(8, 4, 14, 0.85) 100%);
}
.mf-screen--bonus .mf-screen__shade {
  background:
    radial-gradient(ellipse at 50% 45%, rgba(20, 4, 36, 0.32) 0%, rgba(14, 4, 26, 0.62) 70%, rgba(8, 2, 16, 0.86) 100%);
}
.mf-screen__canvas {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; pointer-events: none;
}
.mf-screen__count, .mf-screen__tap {
  position: absolute; left: 0; top: 0; transform: translate(-50%, -50%);
  font-family: 'Luckiest Guy', 'Baloo 2', cursive; line-height: 1; white-space: nowrap;
  pointer-events: none; opacity: 0;
}
.mf-screen__count {
  font-size: 80px; letter-spacing: 0.02em; padding-top: 0.12em; color: transparent;
  filter: drop-shadow(0 0 0.14em rgba(255, 150, 40, 0.7)) drop-shadow(0 0.06em 0 #120600);
}
.mf-screen__count::before, .mf-screen__count::after {
  content: attr(data-value); position: absolute; left: 0; top: 0; padding-top: inherit;
}
.mf-screen__count::before { color: #2a1004; -webkit-text-stroke: 0.16em #2a1004; }
.mf-screen__count::after {
  color: #ffd23a;
  background: linear-gradient(180deg, #fff8c8 12%, #ffd23a 50%, #ff8a00 92%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.mf-screen__tap {
  font-size: 22px; letter-spacing: 0.06em; color: #fff;
  text-shadow:
    0 0 0.08em #2a1004, 0.06em 0.06em 0 #2a1004, -0.06em 0.06em 0 #2a1004,
    0.06em -0.06em 0 #2a1004, -0.06em -0.06em 0 #2a1004, 0 0.12em 0.3em rgba(0, 0, 0, 0.7),
    0 0 0.6em rgba(255, 140, 40, 0.65);
  transition: opacity 400ms ease-out;
}
.mf-screen--bonus .mf-screen__tap {
  text-shadow:
    0 0 0.08em #2a0a4a, 0.06em 0.06em 0 #2a0a4a, -0.06em 0.06em 0 #2a0a4a,
    0.06em -0.06em 0 #2a0a4a, -0.06em -0.06em 0 #2a0a4a, 0 0.12em 0.3em rgba(0, 0, 0, 0.7),
    0 0 0.6em rgba(190, 100, 255, 0.8);
}
.mf-screen.is-ready .mf-screen__tap { opacity: 1; animation: mf-screen-tap 1.6s ease-in-out infinite; }
@keyframes mf-screen-tap {
  0%, 100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  50% { opacity: 0.6; transform: translate(-50%, -50%) scale(0.95); }
}
`;

  let stage = null;
  let canvasEl = null;
  let rootEl = null;
  let bgEl = null;
  let countEl = null;
  let tapEl = null;
  let loadPromise = null;
  let queue = Promise.resolve();

  const variant = () => (window.matchMedia('(orientation: portrait)').matches ? 'mob' : 'desk');
  const absUrl = (src) => new URL(src, location.href).href;

  function webglAvailable(canvas) {
    try {
      return !!(canvas.getContext('webgl2', { alpha: true }) || canvas.getContext('webgl', { alpha: true }));
    } catch {
      return false;
    }
  }

  function buildDom() {
    const host = document.getElementById('screen') || document.body;
    if (!document.getElementById('mf-screen-style')) {
      const style = document.createElement('style');
      style.id = 'mf-screen-style';
      style.textContent = CSS;
      document.head.appendChild(style);
    }
    rootEl = document.createElement('div');
    rootEl.className = 'mf-screen';
    rootEl.setAttribute('aria-hidden', 'true');
    bgEl = document.createElement('div');
    bgEl.className = 'mf-screen__bg';
    const shade = document.createElement('div');
    shade.className = 'mf-screen__shade';
    canvasEl = document.createElement('canvas');
    canvasEl.className = 'mf-screen__canvas';
    countEl = document.createElement('div');
    countEl.className = 'mf-screen__count';
    tapEl = document.createElement('div');
    tapEl.className = 'mf-screen__tap';
    tapEl.textContent = 'TAP TO CONTINUE';
    rootEl.append(bgEl, shade, canvasEl, countEl, tapEl);
    host.appendChild(rootEl);
  }

  function resource(kind, v = variant()) {
    return SpineEngine.SpineResource.load(stage.assetManager, `${SCREEN_ROOT}/${kind}_${v}`, {
      premultipliedAlpha: true, // the generator writes PMA atlases (pma:true)
    });
  }

  function preloadImage(src) {
    return new Promise((resolve) => {
      const im = new Image();
      im.onload = im.onerror = () => resolve();
      im.src = src;
    });
  }

  function load() {
    if (loadPromise) return loadPromise;
    loadPromise = (async () => {
      try {
        if (typeof spine === 'undefined' || typeof SpineEngine === 'undefined') return false;
        buildDom();
        if (!webglAvailable(canvasEl)) return false;
        stage = new SpineEngine.SpineStage(canvasEl);
        const kinds = ['feature', 'bonus'];
        await Promise.all([
          ...kinds.flatMap((k) => ['desk', 'mob'].map((v) => resource(k, v))),
          ...kinds.flatMap((k) => Object.values(BG[k]).map(preloadImage)),
        ]);
        return true;
      } catch (err) {
        console.warn('[MonsterScreens] load failed:', err);
        return false;
      }
    })();
    return loadPromise;
  }

  // Skeleton world -> CSS px relative to the overlay (canvas fills it).
  function boneToCss(bone) {
    const dpr = window.devicePixelRatio || 1;
    return {
      left: (bone.worldX + canvasEl.width / 2) / dpr,
      top: (canvasEl.height / 2 - bone.worldY) / dpr,
      unit: Math.hypot(bone.b, bone.d) / dpr, // CSS px per skeleton unit
    };
  }

  function run(kind, count) {
    return new Promise((resolve) => {
      let v = variant();
      let inst = null;
      let alpha = 1;
      let done = false;
      let closing = false;
      const shownAt = performance.now();
      const total = Math.max(0, Math.round(Number(count) || 0));
      const timers = [];

      const mount = (res, fromEntry) => {
        const next = res.createInstance();
        next.anchorEl = rootEl;
        next.fit = 1;
        next.boundsOverride = BOX[v];
        if (fromEntry && fromEntry.animation) {
          const entry = next.animationState.setAnimation(0, fromEntry.animation.name, fromEntry.loop);
          entry.trackTime = fromEntry.trackTime;
          if (!fromEntry.loop) next.queue('idle', true);
        } else {
          next.play('intro', false);
          next.queue('idle', true);
        }
        next.skeleton.color.a = alpha;
        if (inst) stage.removeOverlay(inst);
        inst = next;
        stage.addOverlay(inst);
      };
      const setBg = () => {
        bgEl.style.backgroundImage = `url("${absUrl(BG[kind][v])}")`;
      };
      const onResize = () => {
        const nv = variant();
        if (nv === v || closing || done) return;
        v = nv;
        setBg();
        const entry = inst && inst.animationState.getCurrent(0);
        resource(kind, v).then((res) => { if (!done) mount(res, entry); }).catch(() => {});
      };

      const frame = () => {
        if (done) return;
        requestAnimationFrame(frame);
        if (!inst || !canvasEl.width) return;
        const tapBone = inst.skeleton.findBone('tap');
        if (tapBone) {
          const p = boneToCss(tapBone);
          tapEl.style.left = `${p.left}px`;
          tapEl.style.top = `${p.top}px`;
          tapEl.style.fontSize = `${TAP_UNITS * p.unit}px`;
        }
        if (kind === 'bonus') {
          const bone = inst.skeleton.findBone('count');
          if (!bone) return;
          const p = boneToCss(bone);
          countEl.style.left = `${p.left}px`;
          countEl.style.top = `${p.top}px`;
          countEl.style.fontSize = `${COUNT_UNITS * p.unit}px`;
          const entry = inst.animationState.getCurrent(0);
          const inIntro = entry && entry.animation && entry.animation.name === 'intro';
          const t = inIntro ? entry.trackTime : Infinity;
          const k = Math.max(0, Math.min(1, (t - COUNT_AT) / COUNT_UP_S));
          const txt = String(Math.round(total * k));
          if (countEl.textContent !== txt) {
            countEl.textContent = txt;
            countEl.dataset.value = txt;
          }
          countEl.style.opacity = t < COUNT_AT ? '0' : String(alpha);
        }
      };

      const finish = () => {
        if (done) return;
        done = true;
        timers.forEach(clearTimeout);
        if (inst) stage.removeOverlay(inst);
        window.removeEventListener('resize', onResize);
        window.removeEventListener('keydown', onKey);
        rootEl.removeEventListener('click', onTap);
        rootEl.classList.remove('is-ready', 'mf-screen--bonus', 'mf-screen--feature');
        countEl.style.opacity = '0';
        resolve();
      };
      const close = () => {
        if (closing || done) return;
        closing = true;
        rootEl.classList.remove('is-open'); // CSS fades the layer out
        const start = performance.now();
        const tick = (now) => {
          if (done) return;
          const f = Math.min(1, (now - start) / FADE_MS);
          alpha = 1 - f;
          if (inst) inst.skeleton.color.a = alpha;
          if (f < 1) requestAnimationFrame(tick);
          else finish();
        };
        requestAnimationFrame(tick);
        timers.push(setTimeout(finish, FADE_MS + 250)); // hidden tab: rAF frozen
      };
      const onTap = () => {
        if (performance.now() - shownAt >= MIN_SHOW_MS) close();
      };
      const onKey = (e) => {
        if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') onTap();
      };

      resource(kind, v).then((res) => {
        setBg();
        countEl.textContent = '';
        countEl.dataset.value = '';
        countEl.style.opacity = '0';
        rootEl.classList.toggle('mf-screen--bonus', kind === 'bonus');
        rootEl.classList.toggle('mf-screen--feature', kind === 'feature');
        mount(res, null);
        void rootEl.offsetWidth;
        rootEl.classList.add('is-open');
        window.addEventListener('resize', onResize);
        window.addEventListener('keydown', onKey);
        rootEl.addEventListener('click', onTap);
        timers.push(setTimeout(() => rootEl.classList.add('is-ready'), MIN_SHOW_MS));
        if (kind === 'bonus') timers.push(setTimeout(close, BONUS_AUTO_CLOSE_MS));
        requestAnimationFrame(frame);
      }).catch((err) => {
        console.warn(`[MonsterScreens] ${kind} screen failed:`, err);
        finish();
      });
    });
  }

  // Resolves once the screen was tapped away (or immediately if it can't run).
  // Calls are serialised: a second show() waits for the first to close.
  function show(kind, { count } = {}) {
    if (kind !== 'feature' && kind !== 'bonus') return Promise.resolve();
    const p = queue.then(() => load()).then((ok) => (ok ? run(kind, count) : undefined));
    queue = p.catch(() => {});
    return queue;
  }

  window.MonsterScreens = { load, show };
})();
